using Microsoft.EntityFrameworkCore;
using footballapp.Models;

namespace footballapp.Data
{
	public class PlayerContext : DbContext
	{

		public PlayerContext( DbContextOptions<PlayerContext> options) : base(options) 
		{

		}

		protected override void OnModelCreating(ModelBuilder modelBuilder)
		{
			modelBuilder.Entity<PlayerStats>().HasKey(ps => new
			{
				ps.PlayerId,
				ps.StatsId
			});

			modelBuilder.Entity<PlayerStats>().HasOne(p => p.Player).WithMany(ps => ps.PlayerStats).HasForeignKey(p => p.PlayerId);
			modelBuilder.Entity<PlayerStats>().HasOne(s => s.Stats).WithMany(ps => ps.PlayerStats).HasForeignKey(s => s.StatsId);

			modelBuilder.Entity<Player>().HasData(
				new Player { Id = 1, Name = "Alex Morgan", ImageUrl = "data:image/webp;base64," }
				);

			modelBuilder.Entity<Stats>().HasData(
				new Stats { Id = 1, Name = "Score= 8.8" },
				new Stats { Id = 1, Name = "Country = US"}
				);

			modelBuilder.Entity<PlayerStats>().HasData(
				new PlayerStats { PlayerId = 1, StatsId = 1 },
				new PlayerStats { PlayerId = 1, StatsId = 2}
				);
				
			base.OnModelCreating(modelBuilder);
		}

		public DbSet<Player> Players { get; set; }
		public DbSet<Stats> Stats {  get; set; }
		public DbSet<PlayerStats> PlayerStats {  get; set; }


	}
}
